3	namespace App\Exceptions;
4	
5	use Exception;
6	use Illuminate\Foundation\Exceptions\Handler as ExceptionHandler;
7	use App\Mail\ExceptionOccuredMail;
8	use Illuminate\Support\Facades\Mail;
9	use Throwable;
10	
11	class Handler extends ExceptionHandler
12	{
13	    /**
14	     * A list of the exception types that are not reported.
15	     *
16	     * @var array
17	     */
18	    protected $dontReport = [
19	        'App\Http\Exceptions\ComingSoonException'
20	    ];
21	
22	    /**
23	     * A list of the inputs that are never flashed for validation exceptions.
24	     *
25	     * @var array
26	     */
27	    protected $dontFlash = [
28	        'password',
29	        'password_confirmation',
30	    ];
31	
32	    /**
33	     * Report or log an exception.
34	     *
35	     * @param  \Exception  $exception
36	     * @return void
37	     */
38	    public function report(Throwable $exception)
39	    {
40	        // riporta sempre errore via mail se eccezione è idonea e se sono in produzione
41	        if (app()->config->get("app.env") == 'production' && $this->shouldReport($exception)) {
42	            $this->sendEmail($exception);
43	        }
44	
45	        // metodo genitore, scrive anche log di Laravel
46	        parent::report($exception);
47	    }
48	
49	    
50	    /**
51	     * Render an exception into an HTTP response.
52	     *
53	     * @param  \Illuminate\Http\Request  $request
54	     * @param  \Exception  $exception
55	     * @return \Illuminate\Http\Response
56	     */
57	    public function render($request, Throwable $exception)
58	    {
59	   
60	        if ($exception instanceof \Illuminate\Http\Exceptions\PostTooLargeException) {
61	            return response("Il file caricato è troppo pesante.", 500);
62	        }
63	
64	        // se app è in debug mode mostra pagina del logger (Whoops) con dettagli dell'errore,
65	        // altrimenti esegue il render della vista di errore corrispondente al codice di risposta
66	        return parent::render($request, $exception);
67	    }
68	
69	
70	    /**
71	     * Invia mail di notifica
72	     */
73	    protected function sendEmail(Throwable $exception) {
74	
75	        $e = new ExceptionOccuredMail($exception->__toString());
76	
77	        $e->to(app()->config->get("errors.alert_mail"))->subject("Errore sito - ".config("app.name"));
78	
79	        // invio mail con libreria default di Laravel        
80	        try {
81	            Mail::send($e);
82	        } catch (Throwable $e) {
83	            exit("error sending mail ".$e->getMessage());
84	        }
85	
86	        return true;        
87	
88	    }
89	  
90	
91	
92	}
